import { McpError } from "../../project/errors.js";

/**
 * Parser for js/plugins.js. The file is JavaScript generated by the editor:
 *
 *   // Generated by RPG Maker.
 *   // Do not edit this file directly.
 *   var $plugins =
 *   [
 *   {"name":"...","status":true,"description":"...","parameters":{...}},
 *   ...
 *   ];
 *
 * It is parsed as data (the array literal is JSON) and never executed.
 */
export interface PluginEntry {
  name: string;
  status: boolean;
  description: string;
  parameters: Record<string, string>;
  [extra: string]: unknown;
}

export function parsePluginsJs(text: string): PluginEntry[] {
  const marker = /\$plugins\s*=\s*/.exec(text);
  if (!marker) {
    throw new McpError("MALFORMED_DATA", "js/plugins.js does not contain a `$plugins =` assignment.");
  }
  let body = text.slice(marker.index + marker[0].length).trim();
  if (body.endsWith(";")) body = body.slice(0, -1).trimEnd();
  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch (err) {
    throw new McpError(
      "MALFORMED_DATA",
      `js/plugins.js plugin list is not a plain JSON array (it is never executed): ${(err as Error).message}`,
    );
  }
  if (!Array.isArray(parsed)) {
    throw new McpError("MALFORMED_DATA", "js/plugins.js `$plugins` is not an array.");
  }
  return parsed.map((p, i) => {
    if (!p || typeof p !== "object") {
      throw new McpError("MALFORMED_DATA", `js/plugins.js entry ${i} is not an object.`);
    }
    const o = p as Record<string, unknown>;
    return {
      ...o,
      name: String(o.name ?? ""),
      status: o.status === true,
      description: String(o.description ?? ""),
      parameters: (o.parameters && typeof o.parameters === "object" ? o.parameters : {}) as Record<string, string>,
    };
  });
}
